CREATE TABLE IF NOT EXISTS SchemaVersion(Version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO SchemaVersion VALUES(1);
CREATE TABLE IF NOT EXISTS Movie(MovieKey TEXT PRIMARY KEY,Name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS MediaSource(Id TEXT PRIMARY KEY,MovieKey TEXT NOT NULL,Path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS Session(Id TEXT PRIMARY KEY,SourceId TEXT NOT NULL,MovieKey TEXT NOT NULL,OpenedDate TEXT NOT NULL,StartedUtc TEXT NOT NULL,Valid INTEGER NOT NULL,PlayedMs INTEGER NOT NULL,Payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS IX_Session_MovieDate ON Session(MovieKey,OpenedDate);
CREATE INDEX IF NOT EXISTS IX_Session_Source ON Session(SourceId);
CREATE TABLE IF NOT EXISTS SessionDay(SessionId TEXT NOT NULL REFERENCES Session(Id) ON DELETE CASCADE,Date TEXT NOT NULL,StayMs INTEGER NOT NULL,PlayedMs INTEGER NOT NULL,ShortPlayedMs INTEGER NOT NULL,PRIMARY KEY(SessionId,Date));
CREATE TABLE IF NOT EXISTS Segment(Id TEXT PRIMARY KEY,SessionId TEXT NOT NULL REFERENCES Session(Id) ON DELETE CASCADE,SourceId TEXT NOT NULL,StartMs INTEGER NOT NULL,EndMs INTEGER NOT NULL,Payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS IX_Segment_Source ON Segment(SourceId,StartMs);
CREATE TABLE IF NOT EXISTS TimelineEvent(SessionId TEXT NOT NULL REFERENCES Session(Id) ON DELETE CASCADE,Sequence INTEGER NOT NULL,Payload TEXT NOT NULL,PRIMARY KEY(SessionId,Sequence));
CREATE TABLE IF NOT EXISTS IngestionCheckpoint(InstanceId TEXT PRIMARY KEY,Sequence INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS Metadata(Key TEXT PRIMARY KEY,Value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS DeletionTombstone(InstanceId TEXT NOT NULL,MediaEpoch TEXT NOT NULL,PRIMARY KEY(InstanceId,MediaEpoch));
CREATE TABLE IF NOT EXISTS SourceGroup(SourceId TEXT PRIMARY KEY,GroupId TEXT NOT NULL);
